import logging
from threading import Thread

from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.executor import ExecutionError, OutputStream

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class NetcatCollectorBase(Using("tool_executor"),
                          Using("file_getter"),
                          StartableCollector):
    """
          To Start, Stop and Collect UDP or TCP traffic using netcat.
    """

    def __init__(self,
                 port,
                 nc_path=None,
                 options=None,
                 ip_address=None,
                 target_file_name=None,
                 start_timeout=10,
                 stop_timeout=3,
                 **kwargs):
        super(NetcatCollectorBase, self).__init__(**kwargs)
        self._log_path = "/tmp/nc_{name}".format(name=self._name)
        self._port = port
        self._nc_path = "nc" if nc_path is None else nc_path
        self._options = "-u" if options is None else options
        self._ip_address = ip_address
        self._target_file_name = "{name}.dat".format(name=self._name) if target_file_name is None \
            else target_file_name
        self._sudo_prefix = None
        self._process = None
        self._start_timeout = start_timeout
        self._stop_timeout = stop_timeout

    def _setup(self):
        self._check_nc_type()
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._clean_up_process_and_file()

    def _collect(self, target_dir):
        self._file_getter.get_file(
            source_path=self._log_path,
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir,
                target_file_name=self._target_file_name))

    def _teardown(self):
        self._clean_up_process_and_file()

    def _clean_up_process_and_file(self):
        try:
            self._tool_executor.execute(
                '{sudo_prefix}pkill -9 -f -x '
                '"{nc_path} -l {options}{ip_address} {port}"'.format(
                    sudo_prefix=self._sudo_prefix,
                    nc_path=self._nc_path,
                    options=self._options,
                    ip_address=self._ip_address_string,
                    port=self._port_string).encode('utf-8'))
        except ExecutionError as exception:
            logger.debug("Terminating %r process failed: %r", self._nc_path, exception)
        self._tool_executor.execute("{sudo_prefix}rm -f '{log_path}'".format(
            sudo_prefix=self._sudo_prefix,
            log_path=self._log_path).encode('utf-8'))

    def _check_nc_type(self):
        nc_type = self._tool_executor.execute("'{nc_path}' -h |&head -1".format(
            nc_path=self._nc_path).encode('utf-8'))
        if any(type in nc_type for type in [b'OpenBSD', b'Ncat']):
            self._port_string = self._port
            self._ip_address_string = "" if self._ip_address is None \
                else " {}".format(self._ip_address)
        else:
            self._port_string = "-p {}".format(self._port)
            self._ip_address_string = "" if self._ip_address is None \
                else " -s {}".format(self._ip_address)


class SimpleNetcatCollector(NetcatCollectorBase):

    def _start(self):
        start_command = (
            '\'{nc_path}\' -l {options}{ip_address} {port} > {log_path}').format(
            nc_path=self._nc_path,
            options=self._options,
            ip_address=self._ip_address_string,
            port=self._port_string,
            log_path=self._log_path).encode('utf-8')
        self._process = self._tool_executor.start(start_command, use_tty=True)

    def _stop(self):
        self._process.stdin.write("\x03".encode())
        self._wait_till_process_terminated()

    def _wait_till_process_terminated(self):
        self._process.wait(timeout=self._stop_timeout)


class FilteringNetcatCollector(NetcatCollectorBase):

    def __init__(self,
                 filter_func=None,
                 iterator=None,
                 **kwargs):
        super(FilteringNetcatCollector, self).__init__(**kwargs)
        self._filter_func = (lambda x: True) if filter_func is None else filter_func
        self._iterator = OutputStream.__iter__ if iterator is None else iterator
        self._pid = None
        self._thread = None

    def _start(self):
        start_command = (
            '{sudo_prefix}setsid bash -c "echo ""$""$ >&2;'
            '\'{nc_path}\' -l {options}{ip_address} {port}"').format(
            sudo_prefix=self._sudo_prefix,
            nc_path=self._nc_path,
            options=self._options,
            ip_address=self._ip_address_string,
            port=self._port_string).encode('utf-8')
        logger.debug("start_command=%r", start_command)
        self._process = self._tool_executor.start(start_command, use_tty=False)
        self._start_local_capture()
        self._pid = self._process.stderr.read_line(
            timeout=self._start_timeout).decode('utf-8').strip()
        if not self._process.is_running:
            stdout_output = self._process.stdout.read(timeout=2)
            stderr_output = self._process.stderr.read(timeout=2)
            exit_status = self._process.exit_status
            raise ExecutionError(
                stdout=stdout_output,
                stderr=stderr_output,
                exit_status=exit_status)

    def _start_local_capture(self):

        def run():
            with self._open_log_path() as logfile:
                for data in filter(self._filter_func, self._iterator(self._process.stdout)):
                    logfile.write(data)

        self._thread = Thread(target=run)
        self._thread.daemon = True
        self._thread.start()

    def _open_log_path(self):
        return open(self._log_path, "wb")

    def _stop(self):
        _, stderr, exit_status = self._tool_executor.raw_execute(
            "{sudo_prefix}kill -2 -- -{pid}".format(
                sudo_prefix=self._sudo_prefix,
                pid=self._pid).encode('utf-8'))
        if exit_status or stderr:
            logger.warning("Terminating process failed with error '%r'"
                        " with exit_status %r.", stderr, exit_status)
        self._wait_till_process_terminated()

    def _wait_till_process_terminated(self):
        self._thread.join(timeout=self._stop_timeout)
        self._process.wait(timeout=self._stop_timeout)
